import XCTest
@testable import MumeCore

/// The Swift end of the three-language hash contract.
///
/// These constants are byte-identical to the ones in
/// `core/src/test/kotlin/com/mume/core/filters/HashVectorsTest.kt` and to
/// `shared/hash-vectors.json`, all generated by `tools/gen_hash_vectors.py`
/// from the Python that builds the shipped bundle.
///
/// Python writes the password filter; Kotlin reads it on Android; Swift reads
/// it on iOS. A one-bit divergence in any of the three produces no crash — just
/// silently wrong membership answers. For a breached-password check that means
/// telling someone a compromised password is safe.
///
/// The emoji vector is the one that matters most here: `🔒` is a surrogate pair
/// in UTF-16, so hashing `String.utf16` instead of the UTF-8 bytes fails on
/// that line and passes on every other. That is exactly the kind of bug this
/// file exists to catch.
final class HashParityTests: XCTestCase {

    private let vectors: [(input: String, h1: UInt64, h2: UInt64)] = [
        ("", 0xC381_7C01_6BA4_FF30, 0xA8AC_3505_7198_8A20),
        ("a", 0x5F29_C2AA_DD9B_8527, 0xE009_B507_ACA6_58CA),
        ("abc", 0x29E3_2C04_EC3F_9C30, 0xA817_8AEE_D4BA_E1B9),
        ("password", 0xA39E_041E_B9B7_9ED7, 0x44F3_F910_7CF1_384D),
        ("123456", 0x1928_BFA1_2710_C080, 0x2375_1DAB_BD32_18FD),
        ("m\u{FC}nchen", 0x0066_E844_F3DB_1BFC, 0x6B47_B31E_84D9_E732),
        ("example.com", 0x5596_08F2_BA07_D7BF, 0xD143_CCF0_1ED7_616D),
        ("doubleclick.net", 0x87F6_8F78_881C_00E0, 0x5166_240B_0A71_F931),
        ("standardbank.co.za", 0x43B1_46A3_A622_3FCE, 0x2B74_B26F_4F7C_4B42),
        ("the quick brown fox", 0xFEC8_1753_0D02_5724, 0x9198_1A36_A398_FDB7),
        ("\u{0}\u{FF}", 0x8AA0_B906_92B1_A56F, 0x5164_4C77_8877_4CB9),
        ("\u{1F512}emoji", 0x89C7_1DFB_C992_A570, 0xDDD8_0EE9_156A_A228),
        (String(repeating: "A", count: 64), 0x9DBB_843E_9086_7C77, 0x5047_8086_A70E_91D7),
    ]

    func testH1MatchesCanonicalVectors() {
        for v in vectors {
            XCTAssertEqual(
                Hashing.h1(v.input), v.h1,
                "h1 diverged for \(v.input.debugDescription) — Swift and the Python bundle "
                + "builder no longer agree, so every bundle lookup is unreliable"
            )
        }
    }

    func testH2MatchesCanonicalVectors() {
        for v in vectors {
            XCTAssertEqual(Hashing.h2(v.input), v.h2,
                           "h2 diverged for \(v.input.debugDescription)")
        }
    }

    func testDigestIsH1() {
        for v in vectors {
            XCTAssertEqual(Hashing.digest(v.input), v.h1)
        }
    }

    func testMixerMatchesReferenceImplementation() {
        XCTAssertEqual(Hashing.mix(0), 0xE220_A839_7B1D_CDAF)
        XCTAssertEqual(Hashing.mix(1), 0x910A_2DEC_8902_5CC1)
        XCTAssertEqual(Hashing.mix(0x9E37_79B9_7F4A_7C15), 0x6E78_9E6A_A1B9_65F4)
    }

    func testDomainNormalizationMatchesTheOtherImplementations() {
        XCTAssertEqual(DomainNormalizer.normalize("EXAMPLE.com"), "example.com")
        XCTAssertEqual(DomainNormalizer.normalize("example.com."), "example.com")
        XCTAssertEqual(DomainNormalizer.normalize("  Example.Com  "), "example.com")
        XCTAssertEqual(DomainNormalizer.normalize("*.example.com"), "example.com")
        XCTAssertEqual(DomainNormalizer.normalize("example.com:8080"), "example.com")
        // `www.` is deliberately preserved.
        XCTAssertEqual(DomainNormalizer.normalize("www.example.com"), "www.example.com")
    }

    func testParentChainNeverReachesABareTLD() {
        XCTAssertEqual(
            DomainNormalizer.parentChain("a.b.example.com"),
            ["a.b.example.com", "b.example.com", "example.com"]
        )
        XCTAssertFalse(DomainNormalizer.parentChain("a.b.example.com").contains("com"))
    }

    func testParentChainIsCapped() {
        let deep = (1...40).map { "l\($0)" }.joined(separator: ".") + ".example.com"
        XCTAssertEqual(DomainNormalizer.parentChain(deep, maxLabels: 5).count, 5)
    }
}

/// Mirrors `ScoringEngineTest` in Kotlin. Both must produce the same integers
/// for the same findings — that is the whole point of writing the engine twice
/// against one specification rather than sharing a binary.
final class ScoringParityTests: XCTestCase {

    private let engine = ScoringEngine()
    private let policy = ScoringPolicy.default

    private func finding(
        _ id: String, _ severity: Severity,
        _ category: Category = .network, subject: String = "", multiplier: Double = 1.0
    ) -> Finding {
        Finding(ruleId: id, category: category, severity: severity,
                title: "t", detail: "d",
                remediation: severity == .info ? "" : "fix it",
                subjectId: subject, weightMultiplier: multiplier)
    }

    private func score(_ findings: [Finding]) -> ScanResult {
        engine.score(findings: findings, platform: .android,
                     checksRun: findings.count, checksSkipped: 0)
    }

    func testCleanDeviceScores100() {
        let r = score([])
        XCTAssertEqual(r.score, 100)
        XCTAssertEqual(r.grade, .strong)
        XCTAssertTrue(r.deductionsReconcile)
    }

    func testSingleHighFindingCostsItsFullWeight() {
        let r = score([finding("A", .high)])
        XCTAssertEqual(r.score, 86)
        XCTAssertEqual(r.findings.first?.deduction, 14)
    }

    func testInfoFindingsNeverCostPoints() {
        let r = score([finding("A", .info), finding("B", .info, subject: "x")])
        XCTAssertEqual(r.score, 100)
        XCTAssertTrue(r.findings.allSatisfy { $0.deduction == 0 })
    }

    func testDecayMatchesKotlin() {
        // 14 + 14*0.6 + 14*0.36 = 27.44 -> 27. DEVICE_INTEGRITY caps at 40, so
        // the cap does not interfere. Identical assertion to the Kotlin suite.
        let r = score([
            finding("A", .high, .deviceIntegrity, subject: "1"),
            finding("A", .high, .deviceIntegrity, subject: "2"),
            finding("A", .high, .deviceIntegrity, subject: "3"),
        ])
        XCTAssertEqual(r.score, 73)
        XCTAssertTrue(r.deductionsReconcile)
    }

    func testCapWinsWhenDecayWouldExceedIt() {
        let r = score([
            finding("A", .high, .network, subject: "1"),
            finding("A", .high, .network, subject: "2"),
            finding("A", .high, .network, subject: "3"),
        ])
        XCTAssertEqual(r.score, 100 - policy.cap(for: .network))
        XCTAssertEqual(r.categories.first?.cappedAt, policy.cap(for: .network))
    }

    func testOneBadCategoryCannotZeroTheScore() {
        let findings = (1...50).map { finding("A", .critical, .appHygiene, subject: "s\($0)") }
        XCTAssertEqual(score(findings).score, 65)
    }

    func testBadInEveryCategoryCanReachZero() {
        let findings = Category.allCases.flatMap { category in
            (1...10).map { finding("R-\(category.rawValue)", .critical, category, subject: "s\($0)") }
        }
        let r = score(findings)
        XCTAssertEqual(r.score, 0)
        XCTAssertEqual(r.grade, .atRisk)
    }

    func testDeductionsAlwaysReconcile() {
        var generator = SystemRandomNumberGenerator()
        _ = generator
        let severities: [Severity] = [.info, .low, .medium, .high, .critical]
        for seed in 0..<500 {
            var rng = SeededGenerator(seed: UInt64(seed))
            let count = Int(rng.next() % 30) + 1
            let findings = (0..<count).map { i in
                finding("R\(rng.next() % 5)",
                        severities[Int(rng.next() % 5)],
                        Category.allCases[Int(rng.next() % 6)],
                        subject: "s\(i)")
            }
            let r = engine.score(findings: findings, platform: .android,
                                 checksRun: count, checksSkipped: 0)
            XCTAssertTrue(r.deductionsReconcile,
                          "score \(r.score) does not reconcile with its deductions")
            XCTAssertTrue((0...100).contains(r.score))
        }
    }

    func testInputOrderDoesNotChangeOutput() {
        let findings = [
            finding("C", .medium, .appHygiene, subject: "z"),
            finding("A", .critical, .network, subject: "a"),
            finding("B", .low, .dataExposure, subject: "m"),
            finding("A", .critical, .network, subject: "b"),
        ]
        let a = score(findings)
        let b = score(findings.reversed())
        XCTAssertEqual(a.score, b.score)
        XCTAssertEqual(a.findings.map { $0.finding.key }, b.findings.map { $0.finding.key })
        XCTAssertEqual(a.findings.map(\.deduction), b.findings.map(\.deduction))
    }

    func testGradeBandsMatchThePolicy() {
        XCTAssertEqual(policy.grade(for: 100), .strong)
        XCTAssertEqual(policy.grade(for: 90), .strong)
        XCTAssertEqual(policy.grade(for: 89), .good)
        XCTAssertEqual(policy.grade(for: 75), .good)
        XCTAssertEqual(policy.grade(for: 74), .fair)
        XCTAssertEqual(policy.grade(for: 50), .fair)
        XCTAssertEqual(policy.grade(for: 49), .weak)
        XCTAssertEqual(policy.grade(for: 25), .weak)
        XCTAssertEqual(policy.grade(for: 24), .atRisk)
        XCTAssertEqual(policy.grade(for: 0), .atRisk)
    }
}

/// Deterministic generator so the randomised reconciliation test is
/// reproducible across runs and machines.
private struct SeededGenerator: RandomNumberGenerator {
    private var state: UInt64
    init(seed: UInt64) { state = seed &+ 0x9E37_79B9_7F4A_7C15 }
    mutating func next() -> UInt64 {
        state = state &+ 0x9E37_79B9_7F4A_7C15
        return Hashing.mix(state)
    }
}

final class IsoDateParityTests: XCTestCase {

    func testKnownEpochDays() {
        XCTAssertEqual(IsoDate.toEpochDay("1970-01-01"), 0)
        XCTAssertEqual(IsoDate.toEpochDay("1970-01-02"), 1)
        XCTAssertEqual(IsoDate.toEpochDay("1969-12-31"), -1)
        XCTAssertEqual(IsoDate.toEpochDay("2024-01-01"), 19_723)
    }

    func testLeapYears() {
        XCTAssertNotNil(IsoDate.toEpochDay("2024-02-29"))
        XCTAssertNotNil(IsoDate.toEpochDay("2000-02-29"))
        XCTAssertNil(IsoDate.toEpochDay("2023-02-29"))
        XCTAssertNil(IsoDate.toEpochDay("1900-02-29"), "1900 is not a leap year")
    }

    func testMalformedInputReturnsNil() {
        for bad in ["", "2024", "2024-13-01", "2024-00-10", "2024-01-32",
                    "24-01-01", "2024/01/01", "abcd-ef-gh"] {
            XCTAssertNil(IsoDate.toEpochDay(bad), "'\(bad)' should not parse")
        }
    }

    func testDaysBetweenIsSigned() {
        XCTAssertEqual(IsoDate.daysBetween("2026-01-01", "2026-02-01"), 31)
        XCTAssertEqual(IsoDate.daysBetween("2026-02-01", "2026-01-01"), -31)
        XCTAssertNil(IsoDate.daysBetween("bad", "2026-02-01"))
    }
}
